    wire [LPR_LEAVES_C-1:0] lpr_C_leaves; wire lpr_C = lpr_C_leaves[0];
    ot_pl_land_reset_forest #(.DEPTH(5), .LEAVES(LPR_LEAVES_C), .ROOT_LOADS(5)) u_lpr_C (.ck(ck_C), .d(lpr_root), .q(lpr_C_leaves)); // same reset age; physical reach unproved
