    ot_pl_land_reset_forest #(.DEPTH(5), .LEAVES(LPR_LEAVES_L0), .ROOT_LOADS(5)) u_lpr_L0 (.ck(ck_L0), .d(lpr_root), .q(lpr_L0_leaves)); // same reset age; physical reach unproved
